        probe = file("/etc/php-fpm/diagnostics/probe.php")

        def controlled_directory(metadata: dict[str, object] | None) -> bool:
            return bool(
                metadata
                and metadata.get("uid") == 0
                and metadata.get("type") == stat.S_IFDIR
                and isinstance(metadata.get("mode"), int)
