        loaded = (
            load_evidence(entry, report or "", str(row["expected_executable"])) if safe else None
        )
        safe = safe and loaded is not None
        row["load_safe"] = safe
        response = None
        if safe:
            response = run(
                [
                    "timeout",
                    "6",
                    "env",
                    "-i",
                    "SCRIPT_FILENAME=/etc/php-fpm/diagnostics/probe.php",
                    "SCRIPT_NAME=/probe.php",
                    "REQUEST_METHOD=GET",
                    "QUERY_STRING=",
                    fcgi_path + "/bin/cgi-fcgi",
